constexpr Entry kEntry = {
    "gs_ext_main", "int32_t", "const gs_ext_host* host, const gs_ext_plugin** plugin",
    "The function a native extension DLL exports. GameScrcpy calls it once after loading the DLL: set *plugin to "
    "the DLL's own description and return GS_EXT_OK, or GS_EXT_UNSUPPORTED when host->abi_version is not one the DLL "
    "supports. The description, and everything it points to, has to stay valid until unload is called; GameScrcpy "
    "never writes to it."};

